"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["62502"],{47170(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.documento_exigido.aplicabilidade_obrigatoria","status":422,"titulo":"A aplicabilidade da exig\xeancia documental \xe9 obrigat\xf3ria"},"descricao":{"codigo":"uniplus.selecao.documento_exigido.aplicabilidade_obrigatoria","requisitos":["UNI-REQ-0057"],"oQueAconteceu":["Todo documento exigido declara a quem se aplica: `GERAL`, quando \xe9 exigido de todos, ou\\n`CONDICIONAL`, quando \xe9 exigido s\xf3 de quem satisfaz as condi\xe7\xf5es configuradas. O sistema n\xe3o\\ndeduz isso da aus\xeancia de condi\xe7\xf5es. A defini\xe7\xe3o trouxe um documento sem essa declara\xe7\xe3o, ou\\ncom um valor que n\xe3o \xe9 nenhum dos dois.","\xc9 uma confer\xeancia de forma, feita antes de o sistema consultar o tipo de documento, as fases ou\\nas demais configura\xe7\xf5es do processo. Ela examina as exig\xeancias na ordem recebida e para na\\nprimeira que tem defeito; dentro dessa exig\xeancia, os defeitos de forma aparecem juntos (por\\nexemplo, a aplicabilidade ausente e o tamanho m\xe1ximo inv\xe1lido)."],"comoResolver":["Informe `GERAL` ou `CONDICIONAL` para o documento apontado. Em `CONDICIONAL`, informe tamb\xe9m as\\ncondi\xe7\xf5es que decidem de quem o documento \xe9 exigido. Depois, envie a defini\xe7\xe3o de novo."],"ondeAparece":["Defini\xe7\xe3o de documentos exigidos do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Documento exigido"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"e5dad467d85ce0f062b88f68241ad834bc540cf0"}}')}}]);